content.solution:
# Активное окружение сейчас blue.
# Чтобы переключиться на green, поменяйте только строку proxy_pass ниже.

upstream blue {
    server 10.0.0.11:8080;
    server 10.0.0.12:8080;
}

upstream green {
    server 10.0.0.21:8080;
    server 10.0.0.22:8080;
}

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://blue;
        proxy_set_header Host $host;
    }
}
